using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Xml;
namespace NCF {
// Unmodified pinned SVGs are embedded in the EXE. No font substitution or second drawing.
public static class SvgIcons {
 static readonly Dictionary<string,Geometry[]> cache=new Dictionary<string,Geometry[]>();
 static double N(XmlElement e,string name,double fallback){return e.HasAttribute(name)?Double.Parse(e.GetAttribute(name),CultureInfo.InvariantCulture):fallback;}
 public static Geometry[] GeometryFor(string name){lock(cache){Geometry[] found;if(cache.TryGetValue(name,out found))return found;var list=new List<Geometry>();using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("NCF.Icons."+name+".svg")){if(stream==null)throw new IOException("Missing installed vector icon: "+name);var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null};var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(stream,settings))doc.Load(reader);var root=doc.DocumentElement;if(root.Name!="svg"||root.GetAttribute("viewBox")!="0 0 24 24")throw new IOException("Unsupported icon viewport.");foreach(XmlNode node in root.ChildNodes){var e=node as XmlElement;if(e==null)continue;Geometry g;switch(e.LocalName){case "path":g=Geometry.Parse(e.GetAttribute("d"));break;case "rect":double rx=N(e,"rx",0);g=new RectangleGeometry(new Rect(N(e,"x",0),N(e,"y",0),N(e,"width",0),N(e,"height",0)),rx,N(e,"ry",rx));break;case "circle":g=new EllipseGeometry(new Point(N(e,"cx",0),N(e,"cy",0)),N(e,"r",0),N(e,"r",0));break;case "ellipse":g=new EllipseGeometry(new Point(N(e,"cx",0),N(e,"cy",0)),N(e,"rx",0),N(e,"ry",0));break;case "line":g=new LineGeometry(new Point(N(e,"x1",0),N(e,"y1",0)),new Point(N(e,"x2",0),N(e,"y2",0)));break;case "polyline":case "polygon":var points=PointCollection.Parse(e.GetAttribute("points"));var geometry=new StreamGeometry();using(var c=geometry.Open()){if(points.Count>0){c.BeginFigure(points[0],false,e.LocalName=="polygon");for(int i=1;i<points.Count;i++)c.LineTo(points[i],true,false);}}g=geometry;break;default:throw new IOException("Unsupported SVG primitive: "+e.LocalName);}g.Freeze();list.Add(g);}}found=list.ToArray();cache[name]=found;return found;}}
 public static void Draw(DrawingContext dc,string name,Rect bounds,Brush color){if(bounds.Width<=0||bounds.Height<=0)return;double side=Math.Min(bounds.Width,bounds.Height);dc.PushTransform(new TranslateTransform(bounds.Left+(bounds.Width-side)/2,bounds.Top+(bounds.Height-side)/2));dc.PushTransform(new ScaleTransform(side/24,side/24));var pen=new Pen(color,2){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};foreach(var geometry in GeometryFor(name))dc.DrawGeometry(null,pen,geometry);dc.Pop();dc.Pop();}
 public static FrameworkElement Label(string name,string text,double size){var row=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};row.Children.Add(new SvgIcon(name,size));if(!String.IsNullOrEmpty(text))row.Children.Add(new TextBlock{Text=text,Margin=new Thickness(6,0,0,0),VerticalAlignment=VerticalAlignment.Center});return row;}
 public static void Button(Button b,string name,string label,double size){b.Content=Label(name,label,size);b.ToolTip=String.IsNullOrEmpty(label)?name:label;System.Windows.Automation.AutomationProperties.SetName(b,String.IsNullOrEmpty(label)?name:label);}
 public static Style IconButtonStyle(double radius){var style=new Style(typeof(Button));style.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.Transparent));style.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0)));var template=new ControlTemplate(typeof(Button));var border=new FrameworkElementFactory(typeof(Border));border.Name="Surface";border.SetValue(Border.CornerRadiusProperty,new CornerRadius(radius));border.SetValue(Border.BackgroundProperty,new TemplateBindingExtension(Control.BackgroundProperty));var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(content);template.VisualTree=border;var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(Border.BackgroundProperty,new SolidColorBrush(Color.FromRgb(210,216,223)),"Surface"));template.Triggers.Add(hover);var pressed=new Trigger{Property=System.Windows.Controls.Primitives.ButtonBase.IsPressedProperty,Value=true};pressed.Setters.Add(new Setter(Border.BackgroundProperty,new SolidColorBrush(Color.FromRgb(178,200,227)),"Surface"));template.Triggers.Add(pressed);var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(Border.BackgroundProperty,new SolidColorBrush(Color.FromArgb(20,0,0,0)),"Surface"));template.Triggers.Add(disabled);style.Setters.Add(new Setter(Control.TemplateProperty,template));return style;}
}
public sealed class SvgIcon : FrameworkElement {
 public static readonly DependencyProperty IconNameProperty=DependencyProperty.Register("IconName",typeof(string),typeof(SvgIcon),new FrameworkPropertyMetadata("image",FrameworkPropertyMetadataOptions.AffectsRender));
 public string IconName {get{return (string)GetValue(IconNameProperty);}set{SetValue(IconNameProperty,value);}}
 public Brush Stroke;
 public SvgIcon(string name,double size){IconName=name;Width=Height=size;VerticalAlignment=VerticalAlignment.Center;IsHitTestVisible=false;IsEnabledChanged+=delegate{InvalidateVisual();};}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);if(!IsEnabled)dc.PushOpacity(.4);SvgIcons.Draw(dc,IconName,new Rect(0,0,ActualWidth,ActualHeight),Stroke??System.Windows.Documents.TextElement.GetForeground(this));if(!IsEnabled)dc.Pop();}
}
}
